add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_place_order_text_by_gateway' );

function perfectpixel_place_order_text_by_gateway( $gateways ) {
	if ( is_admin() ) {
		return $gateways;
	}
	// Payment method ID => button text.
	$texts = array(
		'bacs' => 'Προβολή στοιχείων τράπεζας',
		'cod'  => 'Ολοκλήρωση με αντικαταβολή',
	);
	foreach ( $texts as $id => $text ) {
		if ( isset( $gateways[ $id ] ) ) {
			$gateways[ $id ]->order_button_text = $text;
		}
	}
	return $gateways;
}
